import re

def is_valid_email(value: str) -> bool:
    pattern = r"^[^\s@]+@[^\s@]+\.[^\s@]+$"
    return bool(re.fullmatch(pattern, value))

assert is_valid_email('ali@example.com')
assert not is_valid_email('ali@')

