import csv
from pathlib import Path

def read_rows(path: str) -> list[dict[str, str]]:
    file = Path(path)
    if not file.is_file():
        raise FileNotFoundError(file)
    with file.open(newline='', encoding='utf-8') as handle:
        return list(csv.DictReader(handle))


